def classify_intent(query):
    query_lower = query.lower().strip()
    scores = {}

    for intent, patterns in INTENT_PATTERNS.items():
        score = 0
        for pattern in patterns:
            if pattern in query_lower:
                score += len(pattern)  # Longer matches score higher
        scores[intent] = score
